-- TOC entry 267 (class 1255 OID 27518)
-- Name: fn_validate_narration_content_target(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_validate_narration_content_target() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_code text;
BEGIN
  SELECT code
  INTO v_code
  FROM public.content_types
  WHERE content_type_id = NEW.content_type_id;

  IF v_code IS NULL THEN
    RAISE EXCEPTION 'Content Type is invalid.';
  END IF;

  IF v_code = 'Place' THEN
    IF NEW.place_id IS NULL OR NEW.dish_id IS NOT NULL THEN
      RAISE EXCEPTION 'Place Narration requires place_id only.';
    END IF;

  ELSIF v_code = 'Dish' THEN
    IF NEW.dish_id IS NULL OR NEW.place_id IS NOT NULL THEN
      RAISE EXCEPTION 'Dish Narration requires dish_id only.';
    END IF;

  ELSIF v_code = 'General' THEN
    IF NEW.place_id IS NOT NULL OR NEW.dish_id IS NOT NULL THEN
      RAISE EXCEPTION 'General Narration must not target place or dish.';
    END IF;

  ELSE
    RAISE EXCEPTION 'Unsupported Content Type: %', v_code;
  END IF;

  RETURN NEW;
END;
$$;


--
-- TOC entry 266 (class 1255 OID 27516)
-- Name: fn_validate_qr_code_target(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_validate_qr_code_target() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_code text;
BEGIN
  SELECT code
  INTO v_code
  FROM public.target_types
  WHERE target_type_id = NEW.target_type_id;

  IF v_code IS NULL THEN
    RAISE EXCEPTION 'Target Type is invalid.';
  END IF;

  IF v_code = 'Place' THEN
    IF NEW.place_id IS NULL OR NEW.dish_id IS NOT NULL OR NEW.narration_id IS NOT NULL THEN
      RAISE EXCEPTION 'Place QR requires place_id only.';
    END IF;

  ELSIF v_code = 'Dish' THEN
    IF NEW.dish_id IS NULL OR NEW.place_id IS NOT NULL OR NEW.narration_id IS NOT NULL THEN
      RAISE EXCEPTION 'Dish QR requires dish_id only.';
    END IF;

  ELSIF v_code = 'Narration' THEN
    IF NEW.narration_id IS NULL OR NEW.place_id IS NOT NULL OR NEW.dish_id IS NOT NULL THEN
      RAISE EXCEPTION 'Narration QR requires narration_id only.';
    END IF;

  ELSE
    RAISE EXCEPTION 'Unsupported Target Type: %', v_code;
  END IF;

  RETURN NEW;
END;
$$;


