INSERT INTO public.dish_categories VALUES (1, 'Hải sản', 'Các món hải sản phổ biến tại phố ẩm thực Vĩnh Khánh', true, '2026-05-20 15:11:04.799591', '2026-05-20 15:11:04.799591');
INSERT INTO public.dish_categories VALUES (2, 'Món nướng', 'Các món nướng than, xiên que, bò, gà và hải sản nướng.', true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116');
INSERT INTO public.dish_categories VALUES (3, 'Lẩu', 'Các món lẩu phù hợp nhóm bạn, gia đình và khách du lịch.', true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116');
INSERT INTO public.dish_categories VALUES (4, 'Cơm - bún - mì', 'Các món ăn no phổ biến cho bữa tối và ăn khuya.', true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116');
INSERT INTO public.dish_categories VALUES (5, 'Ăn vặt', 'Các món ăn nhẹ, khai vị và món đường phố dễ gọi.', true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116');
INSERT INTO public.dish_categories VALUES (6, 'Đồ uống', 'Nước giải khát, trà, sinh tố và đồ uống dùng kèm.', true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116');
INSERT INTO public.dish_categories VALUES (7, 'Tráng miệng', 'Chè, bánh flan, rau câu và món ngọt sau bữa ăn.', true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116');
INSERT INTO public.dish_categories VALUES (8, 'Món chay / Healthy', 'Một số lựa chọn nhẹ bụng, ít dầu mỡ hoặc phù hợp ăn chay.', true, '2026-05-29 14:21:30.384116', '2026-06-04 16:34:01.921254');


