INSERT INTO public.dishes VALUES (1, 'Ốc len xào dừa', 1, 'Ốc len xào dừa là món ăn có vị béo thơm từ nước cốt dừa, thường được nhiều khách chọn khi ăn ốc.', '', 85000.00, true, true, '2026-05-20 15:11:04.799591', '2026-05-20 15:11:04.799591');
INSERT INTO public.dishes VALUES (2, 'Ốc hương rang muối', 1, 'Ốc hương rang muối ớt, thơm và đậm vị.', '', 120000.00, true, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116');
INSERT INTO public.dishes VALUES (3, 'Nghêu hấp sả', 1, 'Nghêu hấp sả nóng, nước dùng thơm nhẹ.', '', 65000.00, false, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116');
INSERT INTO public.dishes VALUES (4, 'Sò điệp nướng mỡ hành', 1, 'Sò điệp nướng mỡ hành và đậu phộng.', '', 95000.00, true, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116');
