INSERT INTO public.narration_contents VALUES (1, 'Giới thiệu Quán Ốc Vĩnh Khánh', 'Quán Ốc Vĩnh Khánh là một điểm dừng chân tiêu biểu trong khu phố ẩm thực Vĩnh Khánh. Nơi đây nổi bật với các món ốc, hải sản và không khí ăn uống đường phố sôi động về đêm.', 1, NULL, 1, true, '2026-05-20 15:11:04.799591', '2026-05-20 15:11:04.799591', 1);
INSERT INTO public.narration_contents VALUES (40, 'Bài test auto translate từ admin', 'Bài test auto translate từ adminn', NULL, NULL, 1, true, '2026-06-08 13:47:17.236751', '2026-06-08 13:54:09.727856', 3);
INSERT INTO public.narration_contents VALUES (2, 'Khám phá Quán Ốc Vĩnh Khánh', 'Quán ốc nổi bật tại phố ẩm thực Vĩnh Khánh, phù hợp cho khách muốn trải nghiệm không khí ăn uống đường phố. Địa chỉ: 40 Đ. Vĩnh Khánh, Khánh Hội, Hồ Chí Minh, Việt Nam. Đây là một điểm dừng trong tuyến trải nghiệm phố ẩm thực Vĩnh Khánh.', 1, NULL, 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 1);
