INSERT INTO public.narration_contents VALUES (30, 'Giới thiệu món Càng ghẹ rang muối', 'Càng ghẹ rang muối là món nổi bật trong nhóm hải sản tại phố ẩm thực Vĩnh Khánh. Càng ghẹ rang muối đậm vị. hợp ăn nhóm. Giá tham khảo khoảng 160.000 VND.', NULL, 7, 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 2);
INSERT INTO public.narration_contents VALUES (31, 'Giới thiệu món Ba chỉ bò nướng', 'Ba chỉ bò nướng là món nổi bật trong nhóm món nướng tại phố ẩm thực Vĩnh Khánh. Ba chỉ bò ướp sốt. nướng tại bàn hoặc nướng sẵn. Giá tham khảo khoảng 129.000 VND.', NULL, 10, 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 2);
INSERT INTO public.narration_contents VALUES (32, 'Giới thiệu món Bạch tuộc nướng', 'Bạch tuộc nướng là món nổi bật trong nhóm món nướng tại phố ẩm thực Vĩnh Khánh. Bạch tuộc nướng giòn dai. sốt cay nhẹ. Giá tham khảo khoảng 140.000 VND.', NULL, 12, 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 2);
INSERT INTO public.narration_contents VALUES (33, 'Giới thiệu món Lẩu Thái hải sản', 'Lẩu Thái hải sản là món nổi bật trong nhóm lẩu tại phố ẩm thực Vĩnh Khánh. Lẩu Thái vị chua cay. dùng kèm hải sản và rau. Giá tham khảo khoảng 220.000 VND.', NULL, 14, 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 2);
