INSERT INTO public.narration_contents VALUES (36, 'Giới thiệu món Bún đậu mẹt nhỏ', 'Bún đậu mẹt nhỏ là món nổi bật trong nhóm cơm - bún - mì tại phố ẩm thực Vĩnh Khánh. Bún đậu. đậu chiên. chả cốm và rau ăn kèm. Giá tham khảo khoảng 89.000 VND.', NULL, 21, 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 2);
INSERT INTO public.narration_contents VALUES (37, 'Giới thiệu món Gỏi xoài khô mực', 'Gỏi xoài khô mực là món nổi bật trong nhóm ăn vặt tại phố ẩm thực Vĩnh Khánh. Gỏi xoài chua ngọt ăn cùng khô mực. Giá tham khảo khoảng 65.000 VND.', NULL, 24, 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 2);
