INSERT INTO public.narration_translations VALUES (1, 1, 2, 'Giới thiệu Quán Ốc Vĩnh Khánh', 'Quán Ốc Vĩnh Khánh là một điểm dừng chân tiêu biểu trong khu phố ẩm thực Vĩnh Khánh. Nơi đây nổi bật với các món ốc, hải sản và không khí ăn uống đường phố sôi động về đêm.', 1, true, '2026-05-20 15:11:04.799591', '2026-05-20 15:11:04.799591', 1);
INSERT INTO public.narration_translations VALUES (2, 2, 2, 'Khám phá Quán Ốc Vĩnh Khánh', 'Quán Ốc Vĩnh Khánh nằm tại 40 Đ. Vĩnh Khánh, Khánh Hội, Hồ Chí Minh, Việt Nam. Quán ốc nổi bật tại phố ẩm thực Vĩnh Khánh, phù hợp cho khách muốn trải nghiệm không khí ăn uống đường phố. Gợi ý: hãy mở bản đồ, kiểm tra khoảng cách và chọn món nổi bật trước khi ghé quán.', 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 1);
INSERT INTO public.narration_translations VALUES (3, 2, 3, 'Discover Quán Ốc Vĩnh Khánh', 'Quán Ốc Vĩnh Khánh is located at 40 Vinh Khanh Street, Khanh Hoi, Ho Chi Minh City, Vietnam. This restaurant is a suggested stop on the Vinh Khanh food street route. You can use the map, QR code, or narration feature to explore it.', 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 1);
