INSERT INTO public.narration_translations VALUES (46, 24, 2, 'Khám phá Khu Hải Sản Tập Trung', 'Khu Hải Sản Tập Trung nằm tại 60 Đ. Vĩnh Khánh, Khánh Hội, Hồ Chí Minh, Việt Nam. Khu vực tập trung nhiều quán hải sản và món ốc. Gợi ý: hãy mở bản đồ, kiểm tra khoảng cách và chọn món nổi bật trước khi ghé quán.', 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 1);
INSERT INTO public.narration_translations VALUES (47, 24, 3, 'Discover Khu Hải Sản Tập Trung', 'Khu Hải Sản Tập Trung is located at 60 Vinh Khanh Street, Khanh Hoi, Ho Chi Minh City, Vietnam. This area is part of the Vinh Khanh food street experience. You can use the map, QR code, or narration feature to explore it.', 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 1);
INSERT INTO public.narration_translations VALUES (48, 25, 2, 'Khám phá Khu Ăn Khuya Vĩnh Khánh', 'Khu Ăn Khuya Vĩnh Khánh nằm tại 230 Đ. Vĩnh Khánh, Khánh Hội, Hồ Chí Minh, Việt Nam. Khu vực có nhiều món ăn no và ăn khuya trên tuyến Vĩnh Khánh. Gợi ý: hãy mở bản đồ, kiểm tra khoảng cách và chọn món nổi bật trước khi ghé quán.', 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 1);
INSERT INTO public.narration_translations VALUES (49, 25, 3, 'Discover Khu Ăn Khuya Vĩnh Khánh', 'Khu Ăn Khuya Vĩnh Khánh is located at 230 Vinh Khanh Street, Khanh Hoi, Ho Chi Minh City, Vietnam. This area is part of the Vinh Khanh food street experience. You can use the map, QR code, or narration feature to explore it.', 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 1);
INSERT INTO public.narration_translations VALUES (50, 26, 2, 'Giới thiệu món Ốc len xào dừa', 'Ốc len xào dừa là món nổi bật trong nhóm hải sản tại phố ẩm thực Vĩnh Khánh. Ốc len béo thơm nước cốt dừa. vị ngọt mặn hài hòa. Giá tham khảo khoảng 85.000 VND.', 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 1);
INSERT INTO public.narration_translations VALUES (51, 26, 3, 'Dish introduction: Ốc len xào dừa', 'Ốc len xào dừa is a highlighted dish in the Hải sản group on Vinh Khanh food street. It is suitable for visitors who want to try a local street-food flavor. Estimated price: 85,000 VND.', 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 1);
INSERT INTO public.narration_translations VALUES (52, 27, 2, 'Giới thiệu món Ốc hương rang muối', 'Ốc hương rang muối là món nổi bật trong nhóm hải sản tại phố ẩm thực Vĩnh Khánh. Ốc hương rang muối ớt. thơm và đậm vị. Giá tham khảo khoảng 120.000 VND.', 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 1);
