INSERT INTO public.narration_translations VALUES (64, 33, 2, 'Giới thiệu món Lẩu Thái hải sản', 'Lẩu Thái hải sản là món nổi bật trong nhóm lẩu tại phố ẩm thực Vĩnh Khánh. Lẩu Thái vị chua cay. dùng kèm hải sản và rau. Giá tham khảo khoảng 220.000 VND.', 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 1);
