INSERT INTO public.narration_translations VALUES (66, 34, 2, 'Giới thiệu món Lẩu bò sa tế', 'Lẩu bò sa tế là món nổi bật trong nhóm lẩu tại phố ẩm thực Vĩnh Khánh. Lẩu bò sa tế cay thơm. nước dùng đậm. Giá tham khảo khoảng 240.000 VND.', 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 1);
