INSERT INTO public.narration_translations VALUES (68, 35, 2, 'Giới thiệu món Cơm tấm sườn bì chả', 'Cơm tấm sườn bì chả là món nổi bật trong nhóm cơm - bún - mì tại phố ẩm thực Vĩnh Khánh. Cơm tấm sườn. bì. chả và nước mắm pha. Giá tham khảo khoảng 65.000 VND.', 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 1);
INSERT INTO public.narration_translations VALUES (69, 35, 3, 'Dish introduction: Cơm tấm sườn bì chả', 'Cơm tấm sườn bì chả is a highlighted dish in the Cơm - bún - mì group on Vinh Khanh food street. It is suitable for visitors who want to try a local street-food flavor. Estimated price: 65,000 VND.', 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 1);
INSERT INTO public.narration_translations VALUES (70, 36, 2, 'Giới thiệu món Bún đậu mẹt nhỏ', 'Bún đậu mẹt nhỏ là món nổi bật trong nhóm cơm - bún - mì tại phố ẩm thực Vĩnh Khánh. Bún đậu. đậu chiên. chả cốm và rau ăn kèm. Giá tham khảo khoảng 89.000 VND.', 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 1);
INSERT INTO public.narration_translations VALUES (71, 36, 3, 'Dish introduction: Bún đậu mẹt nhỏ', 'Bún đậu mẹt nhỏ is a highlighted dish in the Cơm - bún - mì group on Vinh Khanh food street. It is suitable for visitors who want to try a local street-food flavor. Estimated price: 89,000 VND.', 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 1);
INSERT INTO public.narration_translations VALUES (72, 37, 2, 'Giới thiệu món Gỏi xoài khô mực', 'Gỏi xoài khô mực là món nổi bật trong nhóm ăn vặt tại phố ẩm thực Vĩnh Khánh. Gỏi xoài chua ngọt ăn cùng khô mực. Giá tham khảo khoảng 65.000 VND.', 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 1);
INSERT INTO public.narration_translations VALUES (73, 37, 3, 'Dish introduction: Gỏi xoài khô mực', 'Gỏi xoài khô mực is a highlighted dish in the Ăn vặt group on Vinh Khanh food street. It is suitable for visitors who want to try a local street-food flavor. Estimated price: 65,000 VND.', 1, true, '2026-05-29 14:21:30.384116', '2026-05-29 14:21:30.384116', 1);
INSERT INTO public.narration_translations VALUES (74, 38, 2, 'Bài kiểm tra dịch tự động', 'Đây là nội dung kiểm tra chức năng dịch tự động đa ngôn ngữ.', NULL, true, '2026-06-07 18:02:42.015366', '2026-06-07 18:02:42.015366', 1);
INSERT INTO public.narration_translations VALUES (75, 38, 3, 'Automatic translation test', 'This is the content of testing the multilingual automatic translation function.', NULL, false, '2026-06-07 18:02:42.031533', '2026-06-07 18:02:42.031533', 2);
