INSERT INTO public.narration_translations VALUES (77, 38, 9, '자동 번역 테스트', '다국어 자동 번역 기능을 테스트하는 내용입니다.', NULL, false, '2026-06-07 18:02:42.033639', '2026-06-07 18:02:42.033639', 2);
INSERT INTO public.narration_translations VALUES (78, 38, 10, '自动翻译测试', '这是测试多语言自动翻译功能的内容。', NULL, false, '2026-06-07 18:02:42.034492', '2026-06-07 18:02:42.034492', 2);
INSERT INTO public.narration_translations VALUES (79, 1, 3, 'Introducing Vinh Khanh Snail Restaurant', 'Vinh Khanh Snail Restaurant is a typical stop in Vinh Khanh culinary neighborhood. This place stands out for its snail dishes, seafood and vibrant street dining atmosphere at night.', NULL, false, '2026-06-07 18:48:25.457399', '2026-06-07 18:48:25.457399', 2);
INSERT INTO public.narration_translations VALUES (80, 1, 8, 'ヴィン カイン カタツムリ レストランのご紹介', 'Vinh Khanh Snail Restaurant は、ヴィン カインのグルメ街の典型的なレストランです。この場所は、カタツムリ料理、シーフード、そして夜の活気に満ちたストリートダイニングの雰囲気で際立っています。', NULL, false, '2026-06-07 18:48:25.465229', '2026-06-07 18:48:25.465229', 2);
INSERT INTO public.narration_translations VALUES (81, 1, 9, 'Vinh Khanh 달팽이 레스토랑을 소개합니다', 'Vinh Khanh Snail Restaurant은 Vinh Khanh 요리 지역의 전형적인 장소입니다. 이 곳은 달팽이 요리, 해산물, 밤에는 활기 넘치는 길거리 식사 분위기로 유명합니다.', NULL, false, '2026-06-07 18:48:25.466097', '2026-06-07 18:48:25.466097', 2);
INSERT INTO public.narration_translations VALUES (82, 1, 10, '永庆蜗牛餐厅简介', '永庆蜗牛餐厅 (Vinh Khanh Snail Restaurant) 是永庆美食区的典型一站。这个地方以其蜗牛菜肴、海鲜和夜间充满活力的街头餐饮氛围而闻名。', NULL, false, '2026-06-07 18:48:25.466689', '2026-06-07 18:48:25.466689', 2);
INSERT INTO public.narration_translations VALUES (83, 2, 8, 'ヴィン カイン カタツムリ レストランを探索する', 'Vinh Khanh Snail Restaurant は、ベトナム、ホーチミン、カインホイ、40 D. Vinh Khanh にあります。ヴィンカイン食品街にある素晴らしいカタツムリレストラン。ストリートダイニングの雰囲気を体験したいお客様に最適です。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:48:32.629799', '2026-06-07 18:48:32.629799', 2);
INSERT INTO public.narration_translations VALUES (84, 2, 9, 'Vinh Khanh 달팽이 레스토랑 둘러보기', 'Vinh Khanh Snail Restaurant은 베트남 호치민 Khanh Hoi D. Vinh Khanh 40에 위치해 있습니다. Vinh Khanh 음식 거리에 있는 뛰어난 달팽이 레스토랑으로 거리 식사 분위기를 경험하고 싶은 손님에게 적합합니다. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:48:32.630975', '2026-06-07 18:48:32.630975', 2);
INSERT INTO public.narration_translations VALUES (85, 2, 10, '探索永庆蜗牛餐厅', 'Vinh Khanh Snail Restaurant 位于 40 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。永庆美食街上出色的蜗牛餐厅，适合想要体验街头用餐氛围的客人。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:48:32.631806', '2026-06-07 18:48:32.631806', 2);
INSERT INTO public.narration_translations VALUES (86, 3, 8, 'ヴィン カインを探索する ナイト カタツムリ', 'Vinh Khanh Night Snail は、ベトナム、ホーチミン、カインホイ、22 D. Vinh Khanh にあります。夜はにぎやかな雰囲気のカタツムリレストラン。炒め物、蒸し物、グリル料理が豊富。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:48:41.086676', '2026-06-07 18:48:41.086676', 2);
INSERT INTO public.narration_translations VALUES (87, 3, 9, 'Vinh Khanh Night Snail 탐험하기', 'Vinh Khanh Night Snail은 베트남 호치민 Khanh Hoi D. Vinh Khanh 22에 위치해 있습니다. 저녁에는 볶음, 찜, 구이 등 다양한 요리를 즐길 수 있는 분주한 분위기의 달팽이 레스토랑입니다. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:48:41.087566', '2026-06-07 18:48:41.087566', 2);
INSERT INTO public.narration_translations VALUES (88, 3, 10, '探索永庆夜蜗牛', 'Vinh Khanh Night Snail 位于 22 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。晚上的蜗牛餐厅有很多炒、蒸、烤的菜肴，气氛热闹。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:48:41.088158', '2026-06-07 18:48:41.088158', 2);
INSERT INTO public.narration_translations VALUES (89, 4, 8, 'ヴィン カイン シーフード 58 を探索する', 'ヴィン カイン シーフード 58 は、ベトナム、ホーチミン、カインホイ、58 D. Vinh Khanh にあります。エビ、イカ、ハマグリ料理が絶品の人気海鮮料理店。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:50:39.97678', '2026-06-07 18:50:39.97678', 2);
INSERT INTO public.narration_translations VALUES (90, 4, 9, 'Vinh Khanh 해산물 탐험 58', 'Vinh Khanh Seafood 58은 베트남 호치민 Khanh Hoi D. Vinh Khanh 58에 위치해 있습니다. 새우, 오징어, 조개 요리가 뛰어난 인기 해산물 레스토랑입니다. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:50:39.978193', '2026-06-07 18:50:39.978193', 2);
INSERT INTO public.narration_translations VALUES (91, 4, 10, '探索永庆海鲜 58', 'Vinh Khanh Seafood 58 位于 58 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。受欢迎的海鲜餐厅，以虾、鱿鱼和蛤蜊菜肴而闻名。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:50:39.979071', '2026-06-07 18:50:39.979071', 2);
INSERT INTO public.narration_translations VALUES (92, 5, 8, '街角でホタテ貝を発見', 'Scallop Corner Street は、72 D. Vinh Khanh、Khanh Hoi、ホーチミン、ベトナムにあります。玉ねぎの脂を添えたホタテのグリルとファストフードを専門とする小さなシーフード カウンター。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:50:48.580711', '2026-06-07 18:50:48.580711', 2);
INSERT INTO public.narration_translations VALUES (93, 5, 9, '길모퉁이에서 가리비를 발견하세요', 'Scallop Corner Street은 베트남 호치민 Khanh Hoi D. Vinh Khanh 72에 위치하고 있습니다. 양파 지방을 곁들인 가리비 구이와 패스트푸드를 전문으로 하는 작은 해산물 카운터입니다. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:50:48.581944', '2026-06-07 18:50:48.581944', 2);
INSERT INTO public.narration_translations VALUES (94, 5, 10, '探索街角的扇贝', '扇贝角街位于越南胡志明市庆会区 72 D. Vinh Khanh。小型海鲜柜台，专营洋葱肥烤扇贝和快餐。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:50:48.582812', '2026-06-07 18:50:48.582812', 2);
INSERT INTO public.narration_translations VALUES (95, 6, 8, 'ヴィン カイン グリル 88 を探索する', 'Vinh Khanh 88 Grill Restaurant は、88 D. Vinh Khanh、カンホイ、ホーチミン、ベトナムにあります。友人グループ向けの炭火焼きスポット。牛肉、鶏肉、シーフードのグリル料理が豊富です。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:50:56.284778', '2026-06-07 18:50:56.284778', 2);
INSERT INTO public.narration_translations VALUES (96, 6, 9, 'Vinh Khanh Grill 88 둘러보기', 'Vinh Khanh 88 Grill Restaurant은 베트남 호치민 칸호이 D. Vinh Khanh 88에 위치해 있습니다. 여러 친구들과 함께 즐길 수 있는 숯불구이 장소로 쇠고기, 닭고기, 해산물 구이 요리가 다양하게 제공됩니다. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:50:56.285844', '2026-06-07 18:50:56.285844', 2);
INSERT INTO public.narration_translations VALUES (97, 6, 10, '探索 Vinh Khanh Grill 88', 'Vinh Khanh 88 Grill 餐厅位于 88 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。适合朋友聚会的木炭烧烤场所，供应多种烤牛肉、鸡肉和海鲜菜肴。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:50:56.286607', '2026-06-07 18:50:56.286607', 2);
INSERT INTO public.narration_translations VALUES (98, 7, 8, 'タコのグリル 102 を発見', 'グリルドタコ 102 は、102 D. Vinh Khanh、Khanh Hoi、ホーチミン、ベトナムにあります。グリルタコのサテカウンター、素早いサービス、夜の軽食に最適。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:51:02.679659', '2026-06-07 18:51:02.679659', 2);
INSERT INTO public.narration_translations VALUES (99, 7, 9, '문어구이를 만나보세요 102', '구운 문어 102는 베트남 호치민 칸호이 D. Vinh Khanh 102에 위치해 있습니다. 구운 문어 사테이 카운터, 퀵 서비스, 저녁 간식에 적합합니다. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:51:02.68062', '2026-06-07 18:51:02.68062', 2);
INSERT INTO public.narration_translations VALUES (100, 7, 10, '探索烤章鱼 102', 'Grilled Octopus 102 位于 102 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。烤章鱼沙爹柜台，服务快捷，适合晚上小吃。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:51:02.681286', '2026-06-07 18:51:02.681286', 2);
INSERT INTO public.narration_translations VALUES (101, 8, 8, 'ヴィン カイン タイ鍋を発見 118', 'タイ鍋ヴィン カーン 118 は、118 D. Vinh Khanh、Khanh Hoi、Ho Chi Minh、Vietnam にあります。酸っぱいスープが特徴のタイ風海鮮鍋レストラン。団体様にも最適な空間です。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:51:09.219644', '2026-06-07 18:51:09.219644', 2);
INSERT INTO public.narration_translations VALUES (102, 8, 9, '빈칸 타이 핫팟 118을 만나보세요', '태국식 냄비 Vinh Khanh 118은 베트남 호치민 Khanh Hoi D. Vinh Khanh 118에 위치해 있습니다. 매콤하고 신맛이 나는 육수와 단체 손님이 이용하기 적합한 태국 해산물 훠궈 레스토랑입니다. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:51:09.220637', '2026-06-07 18:51:09.220637', 2);
INSERT INTO public.narration_translations VALUES (103, 8, 10, '探索 Vinh Khanh 泰式火锅 118', '泰式火锅 Vinh Khanh 118 位于 118 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。泰式海鲜火锅店，汤底酸辣，适合团体用餐。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:51:09.221698', '2026-06-07 18:51:09.221698', 2);
INSERT INTO public.narration_translations VALUES (104, 9, 8, 'コムタムナイト136を発見', 'Com Tam Night 136 は、136 D. Vinh Khanh、Khanh Hoi、Ho Chi Minh、Vietnam にあります。ブロークンライスレストランは夜も営業しており、街歩きの前に腹ごしらえしたいお客様に最適です。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:51:17.077653', '2026-06-07 18:51:17.077653', 2);
INSERT INTO public.narration_translations VALUES (105, 9, 9, 'Com Tam Night 136을 만나보세요', 'Com Tam Night 136은 베트남 호치민 Khanh Hoi D. Vinh Khanh 136에 위치해 있습니다. 밥집은 밤에도 영업하므로 시내를 산책하기 전 배불리 먹고 싶은 고객에게 적합합니다. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:51:17.078851', '2026-06-07 18:51:17.078851', 2);
INSERT INTO public.narration_translations VALUES (106, 9, 10, '探索 Com Tam 之夜 136', 'Com Tam Night 136 位于 136 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。碎米餐厅晚上营业，适合想在城市里逛逛之前吃饱饭的顾客。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:51:17.079557', '2026-06-07 18:51:17.079557', 2);
INSERT INTO public.narration_translations VALUES (107, 10, 8, 'ウェスタン バン マム 154 を発見する', 'Western Fish Vermicelli 154 は、154 D. Vinh Khanh、Khanh Hoi、ホーチミン、ベトナムにあります。洋風魚醤麺の店は、魚介類のトッピングや付け合わせの野菜がたっぷりで、風味豊かです。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:51:25.004639', '2026-06-07 18:51:25.004639', 2);
INSERT INTO public.narration_translations VALUES (108, 10, 9, '웨스턴 번맘(Western Bun Mam)을 만나보세요 154', '서양 생선 당면 154는 베트남 호치민 칸호이 D. Vinh Khanh 154에 위치하고 있습니다. 양식 액젓 국수 가게는 해산물 토핑과 사이드 야채가 듬뿍 들어있어 맛이 풍부합니다. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:51:25.005653', '2026-06-07 18:51:25.005653', 2);
INSERT INTO public.narration_translations VALUES (109, 10, 10, '发现西式包子妈妈154', '西式鱼粉丝 154 位于 154 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。西式鱼露面店味道浓郁，海鲜配料和配菜很多。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:51:25.006813', '2026-06-07 18:51:25.006813', 2);
INSERT INTO public.narration_translations VALUES (110, 11, 8, 'Bun Dau Vinh Khanh 168 を発見する', 'Bun Dau Vinh Khanh 168 は、168 D. Vinh Khanh、Khanh Hoi、ホーチミン、ベトナムにあります。春雨と豆腐の屋台は小さく、簡単な食事や少人数のグループに適しています。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:51:33.562645', '2026-06-07 18:51:33.562645', 2);
INSERT INTO public.narration_translations VALUES (111, 11, 9, 'Bun Dau Vinh Khanh 168을 발견해보세요', 'Bun Dau Vinh Khanh 168은 베트남 호치민 Khanh Hoi D. Vinh Khanh 168에 위치해 있습니다. 당면과 두부 포장마차는 규모가 작아 간단한 식사나 소그룹 식사에 적합합니다. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:51:33.563579', '2026-06-07 18:51:33.563579', 2);
INSERT INTO public.narration_translations VALUES (112, 11, 10, '探索 Bun Dau Vinh Khanh 168', 'Bun Dau Vinh Khanh 168 位于 168 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。粉丝豆腐摊位不大，适合快餐或者小团体。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:51:33.564493', '2026-06-07 18:51:33.564493', 2);
INSERT INTO public.narration_translations VALUES (113, 12, 8, 'ヴィン カイン スナックを発見 182', 'Vinh Khanh 182 Snacks は、182 D. Vinh Khanh、Khanh Hoi、ホーチミン、ベトナムにあります。スナックエリアではグリルライスペーパー、シェイク、軽食を多数取り揃えています。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:51:39.829685', '2026-06-07 18:51:39.829685', 2);
INSERT INTO public.narration_translations VALUES (114, 12, 9, 'Vinh Khanh 스낵 182를 만나보세요', 'Vinh Khanh 182 Snacks는 베트남 호치민 Khanh Hoi D. Vinh Khanh 182에 위치해 있습니다. 스낵 공간에는 구운 라이스 페이퍼, 셰이크 및 다양한 가벼운 요리가 제공됩니다. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:51:39.830823', '2026-06-07 18:51:39.830823', 2);
INSERT INTO public.narration_translations VALUES (115, 12, 10, '探索永庆小吃 182', 'Vinh Khanh 182 Snacks 位于 182 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。小吃区有烤米纸、奶昔和很多清淡的菜肴。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:51:39.8316', '2026-06-07 18:51:39.8316', 2);
INSERT INTO public.narration_translations VALUES (116, 13, 8, 'レモングラスチキンフィート 198 を発見', 'レモングラスチキンフィート198は、198 D. Vinh Khanh、Khanh Hoi、ホーチミン、ベトナムにあります。レモングラスチキンフィートとマンゴーのサラダ、酸味と辛さがあり食べやすいです。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:51:47.01966', '2026-06-07 18:51:47.01966', 2);
INSERT INTO public.narration_translations VALUES (117, 13, 9, '레몬그라스 닭발을 만나보세요 198', '레몬그라스 치킨피트 198은 베트남 호치민 칸 호이 D. Vinh Khanh 198에 위치해 있습니다. 레몬그라스 닭발과 망고 샐러드가 새콤달콤해서 먹기 편해요. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:51:47.020808', '2026-06-07 18:51:47.020808', 2);
INSERT INTO public.narration_translations VALUES (118, 13, 10, '探索柠檬草凤爪 198', 'Lemongrass Chicken Feet 198 位于 198 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。柠檬草凤爪芒果沙拉，酸酸辣辣，吃起来很方便。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:51:47.02162', '2026-06-07 18:51:47.02162', 2);
INSERT INTO public.narration_translations VALUES (119, 14, 8, 'ディスカバー ビーフ サテ鍋 210', 'ビーフサテーホットポット210は、ベトナム、ホーチミン、カインホイ、210 D. Vinh Khanhにあります。ビーフサテ鍋レストランは風味豊かで、ディナーや深夜の食事に適しています。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:52:27.392732', '2026-06-07 18:52:27.392732', 2);
INSERT INTO public.narration_translations VALUES (120, 14, 9, '쇠고기 사테 핫팟 210을 만나보세요', '쇠고기 사테이 핫팟 210은 베트남 호치민 칸 호이 D. Vinh Khanh 210에 위치해 있습니다. 쇠고기 사테 전골 레스토랑은 맛이 풍부하여 저녁 식사와 심야 식사에 적합합니다. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:52:27.393743', '2026-06-07 18:52:27.393743', 2);
INSERT INTO public.narration_translations VALUES (121, 14, 10, '探索牛肉沙爹火锅 210', '牛肉沙爹火锅 210 位于 210 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。牛肉沙爹火锅店味道浓郁，适合晚餐和宵夜。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:52:27.394348', '2026-06-07 18:52:27.394348', 2);
INSERT INTO public.narration_translations VALUES (142, 21, 10, '探索 Xien Qu Vinh Khanh 318', 'Xien Que Vinh Khanh 318 位于 318 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。为走动的顾客提供烤串和小吃。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:53:21.651133', '2026-06-07 18:53:21.651133', 2);
INSERT INTO public.narration_translations VALUES (122, 15, 8, 'ディスカバー海鮮焼きそば 226', 'シーフード炒め麺 226 の所在地は、226 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnamです。迅速なサービスと手頃な価格の海鮮炒め麺の屋台。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:52:34.417589', '2026-06-07 18:52:34.417589', 2);
INSERT INTO public.narration_translations VALUES (123, 15, 9, '해물볶음면을 만나보세요 226', '해산물 볶음면 226은 베트남 호치민 칸 호이 D. Vinh Khanh 226에 위치해 있습니다. 빠른 서비스와 합리적인 가격을 제공하는 해산물 볶음 국수 노점입니다. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:52:34.418703', '2026-06-07 18:52:34.418703', 2);
INSERT INTO public.narration_translations VALUES (124, 15, 10, '探索海鲜炒面 226', '海鲜炒面226位于226 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。海鲜炒面摊，服务快捷，价格实惠。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:52:34.419495', '2026-06-07 18:52:34.419495', 2);
INSERT INTO public.narration_translations VALUES (125, 16, 8, 'ヴィン カイン タック ティー 240 を探索する', 'Tra Tac Vinh Khanh 240 は、240 D. Vinh Khanh、Khanh Hoi、ホーチミン、ベトナムにあります。観光途中の立ち寄りに最適なビバレッジバー。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:52:41.931569', '2026-06-07 18:52:41.931569', 2);
INSERT INTO public.narration_translations VALUES (126, 16, 9, 'Vinh Khanh Tac Tea 240 탐험하기', 'Tra Tac Vinh Khanh 240은 베트남 호치민 Khanh Hoi D. Vinh Khanh 240에 위치해 있습니다. 관광 투어 도중 잠시 들러보기에 적합한 음료 바입니다. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:52:41.932371', '2026-06-07 18:52:41.932371', 2);
INSERT INTO public.narration_translations VALUES (127, 16, 10, '探索 Vinh Khanh Tac 茶 240', 'Tra Tac Vinh Khanh 240 位于 240 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。适合观光途中休息的饮料吧。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:52:41.933099', '2026-06-07 18:52:41.933099', 2);
INSERT INTO public.narration_translations VALUES (128, 17, 8, 'Khuc Bach 252 Tea を探索する', 'Khuc Bach 252 tea は、252 D. Vinh Khanh、Khanh Hoi、ホーチミン、ベトナムにあります。喫茶店と食後の軽いデザート。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:52:49.87371', '2026-06-07 18:52:49.87371', 2);
INSERT INTO public.narration_translations VALUES (129, 17, 9, 'Khuc Bach 252 차 살펴보기', 'Khuc Bach 252 차는 베트남 호치민 Khanh Hoi D. Vinh Khanh 252에 위치해 있습니다. 식사 후 찻집과 가벼운 디저트. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:52:49.874855', '2026-06-07 18:52:49.874855', 2);
INSERT INTO public.narration_translations VALUES (130, 17, 10, '探索 Khuc Bach 252 茶', 'Khuc Bach 252 茶位于 252 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。茶饮店和餐后的清淡甜点。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:52:49.875565', '2026-06-07 18:52:49.875565', 2);
INSERT INTO public.narration_translations VALUES (131, 18, 8, 'ゴイ クオン ヘルシー 268 を発見する', 'Healthy 268 Goi Cuon は、268 D. Vinh Khanh、Khanh Hoi、ホーチミン、ベトナムにあります。春巻き、サラダ、シンプルなベジタリアン料理などの軽食メニューをご用意しています。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:52:59.079771', '2026-06-07 18:52:59.079771', 2);
INSERT INTO public.narration_translations VALUES (132, 18, 9, '고이 쿠온 헬시 268을 만나보세요', 'Healthy 268 Goi Cuon은 베트남 호치민 Khanh Hoi D. Vinh Khanh 268에 ​​위치해 있습니다. 스프링 롤, 샐러드, 간단한 채식 요리로 구성된 가벼운 옵션입니다. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:52:59.080987', '2026-06-07 18:52:59.080987', 2);
INSERT INTO public.narration_translations VALUES (133, 18, 10, '探索 Goi Cuon 健康 268', 'Healthy 268 Goi Cuon 位于 268 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。清淡的选择包括春卷、沙拉和简单的素食菜肴。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:52:59.081634', '2026-06-07 18:52:59.081634', 2);
INSERT INTO public.narration_translations VALUES (134, 19, 8, '牡蠣のチーズ焼きを発見 282', 'オイスターのチーズ焼き 282 の所在地は、282 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnamです。チーズを添えた牡蠣のバー焼きや、シーフードの簡単グリル料理などをお楽しみいただけます。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:53:05.615639', '2026-06-07 18:53:05.615639', 2);
INSERT INTO public.narration_translations VALUES (135, 19, 9, '치즈 굴구이를 만나보세요 282', '치즈를 곁들인 굴구이 282는 베트남 호치민 칸 호이 D. Vinh Khanh 282에 위치해 있습니다. 바에서 치즈를 곁들인 굴 구이와 빠르게 구운 해산물 요리를 맛보세요. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:53:05.616542', '2026-06-07 18:53:05.616542', 2);
INSERT INTO public.narration_translations VALUES (136, 19, 10, '探索芝士烤牡蛎 282', '奶酪烤牡蛎 282 位于 282 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。酒吧供应奶酪烤牡蛎和快速烤海鲜菜肴。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:53:05.617358', '2026-06-07 18:53:05.617358', 2);
INSERT INTO public.narration_translations VALUES (137, 20, 8, 'クアドン 300 レストランを探索する', 'Cua Dong 300 Restaurant は、ベトナム、ホーチミン、カンホイ、ヴィン カーン 300 D. にあります。美味しい料理を求めるお客様に最適な、かに鍋と素朴な料理のお店です。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:53:14.693624', '2026-06-07 18:53:14.693624', 2);
INSERT INTO public.narration_translations VALUES (138, 20, 9, 'Cua Dong 300 레스토랑 둘러보기', 'Cua Dong 300 레스토랑은 베트남 호치민 Khanh Hoi D. Vinh Khanh 300에 위치해 있습니다. 맛있는 요리를 원하는 고객에게 적합한 게 냄비 요리 레스토랑과 소박한 요리. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:53:14.694571', '2026-06-07 18:53:14.694571', 2);
INSERT INTO public.narration_translations VALUES (139, 20, 10, '探索 Cua Dong 300 餐厅', 'Cua Dong 300 餐厅位于 300 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。螃蟹火锅店和乡村菜肴，适合想要美味佳肴的顾客。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:53:14.695196', '2026-06-07 18:53:14.695196', 2);
INSERT INTO public.narration_translations VALUES (140, 21, 8, 'シエン クエ ビン カイン 318 を探索する', 'Xien Que Vinh Khanh 318 is located at 318 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam. Grilled skewers and snacks for customers walking around.提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:53:21.645083', '2026-06-07 18:53:21.645083', 2);
INSERT INTO public.narration_translations VALUES (141, 21, 9, 'Xien Que Vinh Khanh 318 탐험하기', 'Xien Que Vinh Khanh 318은 베트남 호치민 Khanh Hoi D. Vinh Khanh 318에 위치해 있습니다. 돌아다니는 손님들을 위한 꼬치구이와 안주. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:53:21.650568', '2026-06-07 18:53:21.650568', 2);
INSERT INTO public.narration_translations VALUES (143, 22, 8, 'ヴィン カイン フード ストリート ゲートを探索する', 'ヴィン カーン フード ストリート ゲートは、ベトナム、ホーチミン、カインホイの D. ヴィン カーンにあります。ヴィンカイン屋台体験ルートの出発点。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:53:28.919701', '2026-06-07 18:53:28.919701', 2);
INSERT INTO public.narration_translations VALUES (144, 22, 9, '빈칸 푸드 스트리트 게이트(Vinh Khanh Food Street Gate) 탐험', '빈칸 푸드 스트리트 게이트(Vinh Khanh Food Street Gate)는 베트남 호치민 칸 호이(Khanh Hoi) D. 빈 칸(D. Vinh Khanh)에 위치해 있습니다. 빈칸(Vinh Khanh) 음식거리 체험코스의 시작점. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:53:28.920904', '2026-06-07 18:53:28.920904', 2);
INSERT INTO public.narration_translations VALUES (145, 22, 10, '探索永庆美食街大门', '永庆美食街大门位于越南胡志明市庆会区D. Vinh Khanh。永庆美食街体验路线的起点。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:53:28.921531', '2026-06-07 18:53:28.921531', 2);
INSERT INTO public.narration_translations VALUES (146, 23, 8, 'ヴィン カイン ライト チェックイン エリアを探索する', 'ヴィン カーン ライト チェックイン エリアは、188 D. Vinh Khanh、カンホイ、ホーチミン、ベトナムにあります。通りが明るくなったときにチェックインできる場所で、多くのスナック ショップの近くにあります。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:53:36.167661', '2026-06-07 18:53:36.167661', 2);
INSERT INTO public.narration_translations VALUES (147, 23, 9, 'Vinh Khanh 라이트 체크인 구역 둘러보기', 'Vinh Khanh 라이트 체크인 구역은 188 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam에 위치해 있습니다. 거리가 밝을 때 체크인 장소는 많은 스낵 가게 근처에 있습니다. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:53:36.168595', '2026-06-07 18:53:36.168595', 2);
INSERT INTO public.narration_translations VALUES (148, 23, 10, '探索 Vinh Khanh Light 值机区', 'Vinh Khanh Light 值机区位于 188 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。路灯亮起时的打卡地点，附近有很多小吃店。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:53:36.169156', '2026-06-07 18:53:36.169156', 2);
INSERT INTO public.narration_translations VALUES (149, 24, 8, 'シーフードが集中するエリアを探索する', '集中シーフードエリアは、60 D. Vinh Khanh、Khanh Hoi、ホーチミン、ベトナムにあります。周辺にはシーフードやカタツムリのレストランがたくさんあります。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:54:47.897603', '2026-06-07 18:54:47.897603', 2);
INSERT INTO public.narration_translations VALUES (150, 24, 9, '집중된 해산물 지역을 탐험해보세요', '해산물 집중 구역은 베트남 호치민 칸 호이 D. 빈 칸 60번지에 위치해 있습니다. 이 지역에는 해산물 및 달팽이 레스토랑이 많이 있습니다. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:54:47.898582', '2026-06-07 18:54:47.898582', 2);
INSERT INTO public.narration_translations VALUES (151, 24, 10, '探索海鲜集中区', '海鲜集中区位于越南胡志明市庆会区 60 D. Vinh Khanh。该地区有许多海鲜和蜗牛餐厅。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:54:47.899283', '2026-06-07 18:54:47.899283', 2);
INSERT INTO public.narration_translations VALUES (152, 25, 8, 'ヴィン カーンの深夜ダイニング エリアを探索する', 'ヴィン カーン深夜ダイニング エリアは、ベトナム、ホーチミン、カンホイ、ヴィン カーン、230 D. にあります。このエリアには、ヴィン カイン ルート沿いにたくさんのボリュームのある料理や深夜の料理があります。提案: レストランに行く前に、地図を開いて距離を確認し、注目の料理を選択してください。', NULL, false, '2026-06-07 18:54:54.336567', '2026-06-07 18:54:54.336567', 2);
INSERT INTO public.narration_translations VALUES (153, 25, 9, 'Vinh Khanh 심야 식사 공간 둘러보기', 'Vinh Khanh 심야 식사 공간은 베트남 호치민 Khanh Hoi D. Vinh Khanh 230에 위치해 있습니다. 이 지역에는 빈칸(Vinh Khanh) 노선을 따라 배를 채우는 요리와 심야 요리가 많이 있습니다. 제안: 레스토랑을 방문하기 전에 지도를 열고 거리를 확인하고 추천 요리를 선택하세요.', NULL, false, '2026-06-07 18:54:54.337429', '2026-06-07 18:54:54.337429', 2);
INSERT INTO public.narration_translations VALUES (154, 25, 10, '探索永庆深夜用餐区', 'Vinh Khanh 深夜用餐区位于 230 D. Vinh Khanh, Khanh Hoi, Ho Chi Minh, Vietnam。该地区有许多永庆路线上的丰盛菜肴和深夜菜肴。建议：去餐厅前打开地图，查看距离，选择特色菜品。', NULL, false, '2026-06-07 18:54:54.338074', '2026-06-07 18:54:54.338074', 2);
INSERT INTO public.narration_translations VALUES (155, 26, 8, 'カタツムリのココナッツ炒めのご紹介です', 'カタツムリのココナッツ炒めは、ヴィン カイン フード ストリートのシーフード グループの代表的な料理です。ココナッツミルクの香りがする脂っこいカタツムリ。調和のとれた甘味と塩味。参考価格は約85,000VND。', NULL, false, '2026-06-07 18:55:03.302593', '2026-06-07 18:55:03.302593', 2);
INSERT INTO public.narration_translations VALUES (156, 26, 9, '코코넛을 곁들인 달팽이 볶음을 소개합니다', '코코넛을 곁들인 달팽이 볶음은 Vinh Khanh 푸드 스트리트의 해산물 그룹에서 유명한 요리입니다. 코코넛 밀크 향이 나는 지방이 많은 달팽이입니다. 단맛과 짠맛이 조화로운 맛. 참고 가격은 약 85,000 VND입니다.', NULL, false, '2026-06-07 18:55:03.303468', '2026-06-07 18:55:03.303468', 2);
INSERT INTO public.narration_translations VALUES (157, 26, 10, '椰子炒田螺', '椰子炒田螺是永庆美食街海鲜群中的一道特色菜。肥美的蜗牛，带着椰奶的香味。甜味和咸味和谐。参考价格约为85,000越南盾。', NULL, false, '2026-06-07 18:55:03.303983', '2026-06-07 18:55:03.303983', 2);
INSERT INTO public.narration_translations VALUES (158, 27, 8, 'かたつむりの塩焼きのご紹介です', 'カタツムリの塩焼きは、ヴィン カイン フード ストリートのシーフード グループの代表的な料理です。カタツムリを塩と唐辛子で炒めたもの。香り豊かで風味豊か。参考価格は約12万VND。', NULL, false, '2026-06-07 18:55:10.833693', '2026-06-07 18:55:10.833693', 2);
INSERT INTO public.narration_translations VALUES (159, 27, 9, '소금구이 달팽이를 소개합니다', '소금에 구운 달팽이는 빈칸(Vinh Khanh) 음식 거리의 해산물 그룹에서 유명한 요리입니다. 소금과 칠리를 곁들인 구운 달팽이. 향기롭고 맛이 좋습니다. 참고 가격은 약 120,000 VND입니다.', NULL, false, '2026-06-07 18:55:10.834495', '2026-06-07 18:55:10.834495', 2);
INSERT INTO public.narration_translations VALUES (160, 27, 10, '盐烤蜗牛介绍', '盐烤蜗牛是永庆美食街海鲜群中的一道特色菜。用盐和辣椒烤蜗牛。香浓可口。参考价格约为12万越南盾。', NULL, false, '2026-06-07 18:55:10.835306', '2026-06-07 18:55:10.835306', 2);
INSERT INTO public.narration_translations VALUES (161, 28, 8, 'ホタテ貝柱の玉ねぎグリス焼きのご紹介です', '玉ねぎの脂を添えたホタテのグリルは、ヴィン カイン フード ストリートのシーフード グループの代表的な料理です。ホタテの玉ねぎとピーナッツのグリル。参考価格は約95,000VND。', NULL, false, '2026-06-07 18:55:18.486628', '2026-06-07 18:55:18.486628', 2);
INSERT INTO public.narration_translations VALUES (162, 28, 9, '양파 기름을 곁들인 구운 가리비 소개', '양파 지방을 곁들인 가리비 구이는 빈칸(Vinh Khanh) 음식 거리의 해산물 그룹에서 유명한 요리입니다. 가리비를 양파와 땅콩과 함께 구운 것입니다. 참고 가격은 약 95,000 VND입니다.', NULL, false, '2026-06-07 18:55:18.487548', '2026-06-07 18:55:18.487548', 2);
INSERT INTO public.narration_translations VALUES (163, 28, 10, '洋葱油烤扇贝简介', '洋葱油烤扇贝是永庆美食街海鲜组中的一道特色菜肴。烤扇贝配洋葱和花生。参考价格约为95,000越南盾。', NULL, false, '2026-06-07 18:55:18.488281', '2026-06-07 18:55:18.488281', 2);
INSERT INTO public.narration_translations VALUES (164, 29, 8, 'イカのグリルとサテーのご紹介', 'イカのグリルとサテは、ヴィン カイン フード ストリートのシーフード グループの代表的な料理です。イカのグリルとマイルドなスパイシーなサテー。一般的な使用に適しています。参考価格は約135,000VND。', NULL, false, '2026-06-07 18:55:28.535641', '2026-06-07 18:55:28.535641', 2);
INSERT INTO public.narration_translations VALUES (165, 29, 9, '사테이를 곁들인 구운 오징어를 소개합니다', '사테이를 곁들인 오징어 구이는 빈칸 푸드 스트리트의 해산물 그룹에서 유명한 요리입니다. 살짝 매콤한 사테이를 곁들인 구운 오징어. 일반적인 사용에 적합합니다. 참고 가격은 약 135,000 VND입니다.', NULL, false, '2026-06-07 18:55:28.536787', '2026-06-07 18:55:28.536787', 2);
INSERT INTO public.narration_translations VALUES (166, 29, 10, '介绍烤鱿鱼配沙爹', '沙爹烤鱿鱼是永庆美食街海鲜组中的一道特色菜。烤鱿鱼配微辣沙爹。适合一般用途。参考价格约为135,000越南盾。', NULL, false, '2026-06-07 18:55:28.537442', '2026-06-07 18:55:28.537442', 2);
INSERT INTO public.narration_translations VALUES (167, 30, 8, 'カニ足の塩焼きのご紹介です', 'カニの足の塩焼きは、ヴィン カイン フード ストリートのシーフード グループの代表的な料理です。カニ爪の塩焼きは風味豊かです。グループでの食事に適しています。参考価格は約16万VND。', NULL, false, '2026-06-07 18:55:37.569563', '2026-06-07 18:55:37.569563', 2);
INSERT INTO public.narration_translations VALUES (168, 30, 9, '소금구이 게다리를 소개합니다', '소금에 절인 게 다리는 빈칸(Vinh Khanh) 음식 거리의 해산물 그룹에서 유명한 요리입니다. 소금에 절인 게발톱 구이는 풍미가 풍부합니다. 단체 식사에 적합합니다. 참고 가격은 약 160,000 VND입니다.', NULL, false, '2026-06-07 18:55:37.570654', '2026-06-07 18:55:37.570654', 2);
INSERT INTO public.narration_translations VALUES (169, 30, 10, '盐烤蟹腿介绍', '盐烤蟹腿是永庆美食街海鲜群中的一道特色菜。盐烤蟹爪，味道浓郁。适合团体聚餐。参考价格约为16万越南盾。', NULL, false, '2026-06-07 18:55:37.571499', '2026-06-07 18:55:37.571499', 2);
INSERT INTO public.narration_translations VALUES (170, 31, 8, '牛バラ焼きのご紹介', '牛バラ肉のグリルは、ヴィン カイン フード ストリートのグリル料理群の中でも傑出した料理です。ソースに漬け込んだ牛バラ肉。テーブルでグリルするか、調理済みです。参考価格は約129,000VND。', NULL, false, '2026-06-07 18:55:44.504728', '2026-06-07 18:55:44.504728', 2);
INSERT INTO public.narration_translations VALUES (171, 31, 9, '구운 쇠고기 삼겹살을 소개합니다', '쇠고기 배 구이는 빈칸 음식 거리의 구이 요리 그룹에서 눈에 띄는 요리입니다. 소스에 재운 쇠고기 양지머리. 테이블에서 굽거나 미리 조리해 드세요. 참고 가격은 약 129,000 VND입니다.', NULL, false, '2026-06-07 18:55:44.505852', '2026-06-07 18:55:44.505852', 2);
INSERT INTO public.narration_translations VALUES (172, 31, 10, '介绍烤牛肚', '烤牛肚是永庆美食街烧烤菜肴中的一道特色菜。牛胸肉用酱汁腌制。在餐桌上烤或预先煮熟。参考价格约为129,000越南盾。', NULL, false, '2026-06-07 18:55:44.506547', '2026-06-07 18:55:44.506547', 2);
INSERT INTO public.narration_translations VALUES (173, 32, 8, '焼きたこのご紹介', 'タコのグリルは、ヴィン カイン フード ストリートのグリル料理の中でも傑出した料理です。焼きたこはカリカリ、もちもちです。マイルドなスパイシーなソース。参考価格は約14万VND。', NULL, false, '2026-06-07 18:55:53.758614', '2026-06-07 18:55:53.758614', 2);
INSERT INTO public.narration_translations VALUES (174, 32, 9, '구운 문어를 소개합니다', '문어구이는 빈칸(Vinh Khanh) 음식 거리의 구이 요리 중 가장 눈에 띄는 요리입니다. 구운 문어는 바삭하고 쫄깃해요. 살짝 매콤한 소스. 참고 가격은 약 140,000 VND입니다.', NULL, false, '2026-06-07 18:55:53.760006', '2026-06-07 18:55:53.760006', 2);
INSERT INTO public.narration_translations VALUES (175, 32, 10, '介绍烤章鱼', '烤章鱼是永庆美食街烧烤菜肴中的一道特色菜。烤章鱼酥脆有嚼劲。温和的辣酱。参考价格约为14万越南盾。', NULL, false, '2026-06-07 18:55:53.760838', '2026-06-07 18:55:53.760838', 2);
INSERT INTO public.narration_translations VALUES (176, 33, 8, 'タイの海鮮鍋のご紹介です。', 'タイのシーフード鍋は、ヴィンカイン食品街の鍋グループの代表的な料理です。タイの鍋は酸味と辛味が特徴です。魚介類や野菜と一緒にお召し上がりください。参考価格は約22万VND。', NULL, false, '2026-06-07 18:56:02.353355', '2026-06-07 18:56:02.353355', 2);
INSERT INTO public.narration_translations VALUES (177, 33, 9, '태국 해산물 전골을 소개합니다', '태국 해산물 전골은 빈칸(Vinh Khanh) 음식 거리에 있는 전골 그룹에서 유명한 요리입니다. 태국식 전골은 신맛과 매운 맛이 특징입니다. 해산물과 야채를 곁들여 드세요. 참고 가격은 약 220,000 VND입니다.', NULL, false, '2026-06-07 18:56:02.354523', '2026-06-07 18:56:02.354523', 2);
INSERT INTO public.narration_translations VALUES (178, 33, 10, '介绍泰国海鲜火锅', '泰式海鲜火锅是永庆美食街火锅群中的一道特色菜肴。泰式火锅味道酸辣。与海鲜和蔬菜一起食用。参考价格约为22万越南盾。', NULL, false, '2026-06-07 18:56:02.355499', '2026-06-07 18:56:02.355499', 2);
INSERT INTO public.narration_translations VALUES (179, 34, 8, 'ビーフサテー鍋のご紹介', 'ビーフサテ鍋は、ヴィンカイン食品街の鍋グループの代表的な料理です。香ばしくスパイシーなビーフソテー鍋。濃い色のスープ。参考価格は約24万VND。', NULL, false, '2026-06-07 18:57:26.020345', '2026-06-07 18:57:26.020345', 2);
INSERT INTO public.narration_translations VALUES (180, 34, 9, '쇠고기 사테 전골을 소개합니다', '쇠고기 사테이(Beef satay) 전골은 빈칸(Vinh Khanh) 음식 거리의 전골 그룹에서 눈에 띄는 요리입니다. 향긋하고 매콤한 쇠고기 사테 전골. 어두운 국물. 참고 가격은 약 240,000 VND입니다.', NULL, false, '2026-06-07 18:57:26.021319', '2026-06-07 18:57:26.021319', 2);
INSERT INTO public.narration_translations VALUES (181, 34, 10, '介绍牛肉沙爹火锅', '牛肉沙爹火锅是永庆美食街火锅群中的一道招牌菜。香辣牛肉沙爹火锅。深色肉汤。参考价格约为24万越南盾。', NULL, false, '2026-06-07 18:57:26.022002', '2026-06-07 18:57:26.022002', 2);
INSERT INTO public.narration_translations VALUES (182, 35, 8, 'リブとポークパティのブロークンライスのご紹介です', 'リブとポークパティを添えたブロークン ライスは、ヴィン カイン フード ストリートのライス、バーミセリ、ヌードル グループの代表的な料理です。リブブレイクライス。梱包。ポークパティとミックスナンプラー。参考価格は約65,000VND。', NULL, false, '2026-06-07 18:57:33.789364', '2026-06-07 18:57:33.789364', 2);
INSERT INTO public.narration_translations VALUES (183, 35, 9, '갈비살과 돼지고기 패티를 곁들인 볶음밥을 소개합니다', '갈비와 돼지고기 패티를 곁들인 밥은 빈칸(Vinh Khanh) 음식 거리의 쌀-당면-국수 그룹에서 유명한 요리입니다. 갈비뼈가 부러진 밥. 포장. 돼지고기 패티와 혼합 생선 소스입니다. 참고 가격은 약 65,000VND입니다.', NULL, false, '2026-06-07 18:57:33.790131', '2026-06-07 18:57:33.790131', 2);
INSERT INTO public.narration_translations VALUES (184, 35, 10, '介绍碎米配排骨和肉饼', '排骨肉饼碎饭是永庆美食街米粉面组中的一道特色菜。排骨碎饭。包装。猪肉饼和混合鱼露。参考价格约为65,000越南盾。', NULL, false, '2026-06-07 18:57:33.790847', '2026-06-07 18:57:33.790847', 2);
INSERT INTO public.narration_translations VALUES (185, 36, 8, '小おから春雨のご紹介です', '小さな豆腐春雨は、ヴィン カイン フード ストリートのビーフン、春雨、麺類のグループの中でも傑出した料理です。豆春雨。揚げた豆。ライスパティと付け合わせの野菜。参考価格は約89,000VND。', NULL, false, '2026-06-07 18:57:49.059322', '2026-06-07 18:57:49.059322', 2);
INSERT INTO public.narration_translations VALUES (186, 36, 9, '두부당면 요리를 소개합니다', '작은 두부 당면은 빈칸 음식 거리의 쌀-당면-국수 그룹에서 유명한 요리입니다. 콩 당면. 튀긴 콩. 쌀 패티와 함께 ​​제공되는 야채. 참고 가격은 약 89,000VND입니다.', NULL, false, '2026-06-07 18:57:49.060099', '2026-06-07 18:57:49.060099', 2);
INSERT INTO public.narration_translations VALUES (187, 36, 10, '介绍一下小豆腐粉丝菜', '小豆腐粉丝是永庆美食街米粉面群中的一道特色菜。粉丝。炒豆子。米饭饼和配菜。参考价格约为89,000越南盾。', NULL, false, '2026-06-07 18:57:49.060838', '2026-06-07 18:57:49.060838', 2);
INSERT INTO public.narration_translations VALUES (188, 37, 8, 'ドライマンゴーイカのサラダのご紹介です', 'ドライマンゴーとイカのサラダは、ヴィン カイン フード ストリートのスナック グループの代表的な料理です。甘酸っぱいマンゴーのサラダにスルメを添えました。参考価格は約65,000VND。', NULL, false, '2026-06-07 18:57:54.470349', '2026-06-07 18:57:54.470349', 2);
INSERT INTO public.narration_translations VALUES (189, 37, 9, '말린 망고 오징어 샐러드를 소개합니다', '말린 망고와 오징어 샐러드는 빈칸 푸드 스트리트의 스낵 그룹에서 눈에 띄는 요리입니다. 새콤달콤한 망고 샐러드와 말린 오징어가 함께 제공됩니다. 참고 가격은 약 65,000VND입니다.', NULL, false, '2026-06-07 18:57:54.47136', '2026-06-07 18:57:54.47136', 2);
INSERT INTO public.narration_translations VALUES (190, 37, 10, '介绍干芒果鱿鱼沙拉', '芒果干鱿鱼沙拉是永庆美食街小吃群中的一道招牌菜。糖醋芒果沙拉配干鱿鱼。参考价格约为65,000越南盾。', NULL, false, '2026-06-07 18:57:54.471916', '2026-06-07 18:57:54.471916', 2);
INSERT INTO public.narration_translations VALUES (191, 39, 2, 'Bài test auto translate từ admin', 'Bài test auto translate từ admin', NULL, true, '2026-06-08 13:47:16.85722', '2026-06-08 13:47:16.85722', 1);
