INSERT INTO public.places VALUES (1, 'Quán Ốc Vĩnh Khánh', '40 Đ. Vĩnh Khánh, Khánh Hội, Hồ Chí Minh, Việt Nam', 'Quán ốc nổi bật tại phố ẩm thực Vĩnh Khánh, phù hợp cho khách muốn trải nghiệm không khí ăn uống đường phố.', 10.7618245, 106.6996339, '17:00 - 23:30', '', true, '2026-05-20 15:11:04.799591', '2026-05-29 19:56:15.371085', true, true, 80, 10, 10, 300, 1, 3);
