INSERT INTO public.places VALUES (9, 'Bún Mắm Miền Tây 154', '154 Đ. Vĩnh Khánh, Khánh Hội, Hồ Chí Minh, Việt Nam', 'Quán bún mắm miền Tây đậm vị, nhiều topping hải sản và rau ăn kèm.', 10.7608558, 106.7046422, '15:30 - 22:30', '', true, '2026-05-29 14:21:30.384116', '2026-05-29 15:07:05.097619', true, true, 65, 7, 10, 300, 1, 3);
INSERT INTO public.places VALUES (4, 'Sò Điệp Góc Phố', '72 Đ. Vĩnh Khánh, Khánh Hội, Hồ Chí Minh, Việt Nam', 'Quầy hải sản nhỏ chuyên sò điệp nướng mỡ hành và món ăn nhanh.', 10.7613653, 106.7000699, '17:00 - 23:00', '', true, '2026-05-29 14:21:30.384116', '2026-05-29 19:57:17.654058', true, true, 60, 7, 10, 300, 2, 2);
INSERT INTO public.places VALUES (10, 'Bún Đậu Vĩnh Khánh 168', '168 Đ. Vĩnh Khánh, Khánh Hội, Hồ Chí Minh, Việt Nam', 'Quầy bún đậu mẹt nhỏ, phù hợp ăn nhanh hoặc đi nhóm ít người.', 10.7629224, 106.7024115, '15:00 - 22:30', '', true, '2026-05-29 14:21:30.384116', '2026-05-29 14:28:49.464154', true, true, 55, 6, 10, 300, 2, 2);
INSERT INTO public.places VALUES (11, 'Ăn Vặt Vĩnh Khánh 182', '182 Đ. Vĩnh Khánh, Khánh Hội, Hồ Chí Minh, Việt Nam', 'Khu ăn vặt có bánh tráng nướng, khoai lắc và nhiều món nhẹ.', 10.7643755, 106.7011296, '15:00 - 23:00', '', true, '2026-05-29 14:21:30.384116', '2026-05-29 14:28:55.863211', true, true, 55, 6, 10, 300, 2, 2);
INSERT INTO public.places VALUES (12, 'Chân Gà Sả Tắc 198', '198 Đ. Vĩnh Khánh, Khánh Hội, Hồ Chí Minh, Việt Nam', 'Quầy chân gà sả tắc và gỏi xoài, vị chua cay dễ ăn.', 10.7637244, 106.7016934, '16:00 - 23:30', '', true, '2026-05-29 14:21:30.384116', '2026-05-29 14:29:02.764447', true, true, 50, 6, 10, 300, 2, 2);
INSERT INTO public.places VALUES (14, 'Mì Xào Hải Sản 226', '226 Đ. Vĩnh Khánh, Khánh Hội, Hồ Chí Minh, Việt Nam', 'Quầy mì xào hải sản phục vụ nhanh, giá dễ tiếp cận.', 10.7643755, 106.7011296, '16:30 - 23:00', '', true, '2026-05-29 14:21:30.384116', '2026-05-29 14:29:40.644086', true, true, 55, 5, 10, 300, 2, 2);
INSERT INTO public.places VALUES (15, 'Trà Tắc Vĩnh Khánh 240', '240 Đ. Vĩnh Khánh, Khánh Hội, Hồ Chí Minh, Việt Nam', 'Quầy nước giải khát, phù hợp dừng chân giữa tuyến tham quan.', 10.7637244, 106.7016934, '14:00 - 00:30', '', true, '2026-05-29 14:21:30.384116', '2026-05-29 14:29:51.021998', true, true, 45, 5, 10, 300, 2, 2);
INSERT INTO public.places VALUES (13, 'Lẩu Bò Sa Tế 210', '210 Đ. Vĩnh Khánh, Khánh Hội, Hồ Chí Minh, Việt Nam', 'Quán lẩu bò sa tế đậm vị, thích hợp ăn tối và ăn khuya.', 10.7629224, 106.7024115, '17:00 - 00:00', '', true, '2026-05-29 14:21:30.384116', '2026-05-29 14:29:33.402526', true, true, 80, 8, 10, 300, 1, 3);
